export async function loadLanguage(language: string): Promise<LanguageInput[]> { const url = grammarUrls[language]; if (!url) throw new Error("unknown language: " + language); return (await import(url.href) as { default: LanguageInput[] }).default; }
export async function loadRegexRecipes(language: string): Promise<import("./regex.js").RegexRecipes> { const url = recipeUrls[language]; if (!url) throw new Error("unknown language: " + language); return (await import(url.href) as { default: import("./regex.js").RegexRecipes }).default; }
